import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  index,
  integer,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';

import { productStatus } from './enums';
import { commerce } from './schema';

/**
 * D-172 Phase 1 — fashion catalog core (roadmap §1.1–§1.4).
 *
 * Conventions held across every table:
 * - uuid identifiers (roadmap §1.1–§1.4), generated by PostgreSQL
 *   (`gen_random_uuid()`, built in on PostgreSQL 13+; the local stack runs 16).
 * - `timestamptz` audit columns where the roadmap specifies them.
 * - money and stock are integers: `bigint` in integer Iranian Toman (D-010),
 *   never floating point. Domain writes enforce the canonical 10¹² ceiling
 *   (D-114); `bigint` keeps exactness beyond any realistic basket.
 * - a plain "unique" is already an index, so §1.1/§1.2's "unique, index" is
 *   realised as a UNIQUE constraint (no duplicate index is created).
 * - a column the roadmap does not mark "nullable" is NOT NULL.
 */

/** §1.1 — categories, self-referential for subcategories. */
export const categories = commerce.table(
  'categories',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    name: varchar('name', { length: 255 }).notNull(),
    slug: varchar('slug', { length: 255 }).notNull().unique(),
    parentId: uuid('parent_id').references((): AnyPgColumn => categories.id, {
      onDelete: 'restrict',
    }),
    description: text('description'),
    createdAt: timestamp('created_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [index('categories_parent_id_idx').on(table.parentId)],
);

/** §1.2 — products. */
export const products = commerce.table(
  'products',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    categoryId: uuid('category_id')
      .notNull()
      .references(() => categories.id, { onDelete: 'restrict' }),
    title: varchar('title', { length: 500 }).notNull(),
    slug: varchar('slug', { length: 500 }).notNull().unique(),
    basePrice: bigint('base_price', { mode: 'number' }).notNull(),
    discountPrice: bigint('discount_price', { mode: 'number' }),
    descriptionRaw: text('description_raw').notNull(),
    descriptionHtml: text('description_html').notNull(),
    fabricType: varchar('fabric_type', { length: 120 }).notNull(),
    season: varchar('season', { length: 120 }).notNull(),
    careInstructions: text('care_instructions'),
    status: productStatus('status').notNull().default('DRAFT'),
    createdAt: timestamp('created_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    index('products_category_id_idx').on(table.categoryId),
    index('products_status_idx').on(table.status),
    check('products_base_price_non_negative', sql`${table.basePrice} >= 0`),
    check(
      'products_discount_price_non_negative',
      sql`${table.discountPrice} is null or ${table.discountPrice} >= 0`,
    ),
  ],
);

/** §1.3 — product_variants: the size × color matrix, SKU and stock. */
export const productVariants = commerce.table(
  'product_variants',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    productId: uuid('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    sku: varchar('sku', { length: 120 }).notNull().unique(),
    colorName: varchar('color_name', { length: 120 }).notNull(),
    colorHex: varchar('color_hex', { length: 32 }).notNull(),
    size: varchar('size', { length: 64 }).notNull(),
    stockQuantity: integer('stock_quantity').notNull().default(0),
    priceOverride: bigint('price_override', { mode: 'number' }),
    isActive: boolean('is_active').notNull().default(true),
  },
  (table) => [
    index('product_variants_product_id_idx').on(table.productId),
    check('product_variants_stock_non_negative', sql`${table.stockQuantity} >= 0`),
    check(
      'product_variants_price_override_non_negative',
      sql`${table.priceOverride} is null or ${table.priceOverride} >= 0`,
    ),
    // One variant row per product × size × color name (the matrix contract of
    // §1.3 and the Phase 2.1 generator).
    uniqueIndex('product_variants_matrix_unique').on(
      table.productId,
      table.size,
      table.colorName,
    ),
  ],
);

/** §1.4 — product_images, optionally bound to a single variant. */
export const productImages = commerce.table(
  'product_images',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    productId: uuid('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    variantId: uuid('variant_id').references(() => productVariants.id, {
      // Deleting a variant must not delete the product's media; the image stays
      // attached to the product and loses only its variant binding.
      onDelete: 'set null',
    }),
    storagePath: text('storage_path').notNull(),
    publicUrl: text('public_url').notNull(),
    displayOrder: integer('display_order').notNull().default(0),
    isPrimary: boolean('is_primary').notNull().default(false),
  },
  (table) => [
    index('product_images_product_id_idx').on(table.productId),
    index('product_images_variant_id_idx').on(table.variantId),
  ],
);
